using UnityEngine;
using UnityEngine.InputSystem;
namespace RTS {
public class Battlefield : MonoBehaviour {
 Match match=new(); Camera view; float accumulator; int placing=-1; bool paused; readonly System.Collections.Generic.List<GameObject> bodies=new();
 void Start(){view=new GameObject("Battle Camera").AddComponent<Camera>();view.orthographic=true;view.orthographicSize=18;view.transform.position=new Vector3(32,35,16);view.transform.rotation=Quaternion.Euler(90,0,0);view.backgroundColor=Color.black;view.clearFlags=CameraClearFlags.SolidColor;var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.name="Battlefield";ground.transform.position=new Vector3(64,-.5f,16);ground.transform.localScale=new Vector3(128,1,32);ground.GetComponent<Renderer>().material.color=new Color(.18f,.3f,.17f);new GameObject("Sun").AddComponent<Light>().type=LightType.Directional;}
 void Update(){if(!paused){accumulator+=Time.deltaTime;while(accumulator>=.05f){match.Step(.05f);accumulator-=.05f;}}var touch=Touchscreen.current;if(touch!=null&&touch.primaryTouch.press.wasReleasedThisFrame){Vector2 p=touch.primaryTouch.position.ReadValue();if(p.y<Screen.height-160&&p.y>110){Ray r=view.ScreenPointToRay(p);if(new Plane(Vector3.up,Vector3.zero).Raycast(r,out float d)){var hit=r.GetPoint(d);if(placing>=0&&match.Place(placing,new Vector2(hit.x,hit.z)))placing=-1;else if(match.phase==Phase.Combat)foreach(var s in match.soldiers)if(s.faction==0)s.destination=new Vector2(hit.x,hit.z);}}}
 while(bodies.Count<match.soldiers.Count){var o=GameObject.CreatePrimitive(PrimitiveType.Capsule);o.transform.localScale=new Vector3(.35f,.5f,.35f);bodies.Add(o);}for(int i=0;i<bodies.Count;i++){var s=match.soldiers[i];bodies[i].SetActive(s.health>0);bodies[i].transform.position=new Vector3(s.position.x,.5f,s.position.y);bodies[i].GetComponent<Renderer>().material.color=s.faction==0?Color.cyan:Color.red;}}
 void OnGUI(){GUI.skin.button.fontSize=18;if(GUI.Button(new Rect(12,12,70,50),"Gear"))paused=!paused;if(paused){GUI.Box(new Rect(90,12,240,190),"Paused");if(GUI.Button(new Rect(100,45,220,40),"Save"))Save();if(GUI.Button(new Rect(100,90,220,40),"Load"))Load();if(GUI.Button(new Rect(100,135,220,40),"Resume"))paused=false;return;}
 if(match.phase==Phase.Preparation){GUI.Box(new Rect(90,10,Screen.width-100,65),$"Coins: {match.coins}    Deploy: {Mathf.CeilToInt(match.remaining)}s");float w=(Screen.width-20)/8f;for(int i=0;i<8;i++)if(GUI.Button(new Rect(10+i*w,80,w-3,60),Match.Names[i]+"\n"+Match.Prices[i])){if(match.Buy(i))placing=match.groups[match.groups.Count-1].slot;}}
 for(int slot=0;slot<10;slot++){int n=slot;var g=match.groups.Find(x=>x.slot==n);float w=Screen.width/10f;if(GUI.Button(new Rect(slot*w,Screen.height-90,w-3,80),g==null?(slot+1).ToString():$"{slot+1} {Match.Names[g.type]}\n{g.mode}\n{(g.placed?"Placed":"Place")}")){if(g!=null){if(match.phase==Phase.Preparation)placing=slot;else g.mode=(Mode)(((int)g.mode+1)%3);}}}
 if(match.phase>=Phase.Victory){GUI.Box(new Rect(Screen.width/2-150,Screen.height/2-70,300,140),match.phase.ToString());if(GUI.Button(new Rect(Screen.width/2-100,Screen.height/2,200,50),"Retry")){foreach(var b in bodies)Destroy(b);bodies.Clear();match=new Match();}}}
 void Save(){var path=System.IO.Path.Combine(Application.persistentDataPath,"match.json");System.IO.File.WriteAllText(path+".tmp",JsonUtility.ToJson(match));if(System.IO.File.Exists(path))System.IO.File.Replace(path+".tmp",path,path+".bak");else System.IO.File.Move(path+".tmp",path);}
 void Load(){var path=System.IO.Path.Combine(Application.persistentDataPath,"match.json");if(!System.IO.File.Exists(path))return;foreach(var b in bodies)Destroy(b);bodies.Clear();match=JsonUtility.FromJson<Match>(System.IO.File.ReadAllText(path));}
 void OnApplicationPause(bool value){if(value){paused=true;Save();}}
}}
